def answer():
    """Spectral radius of the Petersen graph adjacency matrix."""
    import numpy as np
    edges = [(0,1),(0,4),(0,5),(1,2),(1,6),(2,3),(2,7),
             (3,4),(3,8),(4,9),(5,7),(5,8),(6,8),(6,9),(7,9)]
    A = np.zeros((10, 10))
    for i, j in edges:
        A[i, j] = 1.0
        A[j, i] = 1.0
    return float(np.max(np.linalg.eigvalsh(A)))
